export class NotFound extends Error {
  constructor(what: string) {
    super(`${what} not found`);
    this.name = 'NotFound';
  }
}

export class RuleBlocked extends Error {
  constructor(public findings: Finding[]) {
    super(
      findings
        .filter((f) => f.level === 'block')
        .map((f) => f.message)
        .join(' '),
    );
    this.name = 'RuleBlocked';
  }
}

export class BadRequest extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'BadRequest';
  }
}

/**
 * Arms trading is switched off. Thrown without writing anything, because the caller's transaction rolls back on a throw;
 * the caller writes the refusal with logTradeRefusal in a transaction of its own.
 */
export class TradingOff extends BadRequest {
  constructor(public readonly what: string, public readonly companyId: string | null) {
    super('Arms trading is switched off until the CEO starts it.');
    this.name = 'TradingOff';
  }
}

/**
 * The comment every approval needs (Fauzan, 31 Oct 2026: "every approval need reason to approve it. the smallest is
 * ok"). Any non-blank text passes; it is trimmed and kept to 500 characters. Used by the HR approvals (slice 3A).
 */
/** A real calendar date in YYYY-MM-DD (rejects 2026-02-30 and the like). */
function realDate(v: unknown): v is IsoDate {
  if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(v)) return false;
  const d = new Date(`${v}T00:00:00Z`);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === v;
}

/** An allowance list compared by type, name and amount, order kept. */
function allowanceKey(list: { label: string; amount: number; typeId?: Id }[] | undefined | null) {
  return (list ?? []).map((a) => [a.typeId ?? '', a.label, a.amount]);
}

export function requireApprovalReason(text: string | null | undefined, what = 'approve'): string {
  const t = (text ?? '').trim();
  if (!t) throw new BadRequest(`Write a comment to ${what}. A short one is fine.`);
  return t.slice(0, 500);
}

/**
 * A refusal that keeps what was already saved in the same request (review finding, 1 Nov 2026): a lapsed approval is
 * returned to the preparer and logged even when the release or return that found it is refused. The API commits the
 * transaction before answering 400; anything else that throws rolls back as usual.
 */
export class RefusedAfterSave extends BadRequest {
  constructor(message: string) {
    super(message);
    this.name = 'RefusedAfterSave';
  }
}

/** A stale version or a closed record: the screen must load it again (HTTP 409). */
export class ReviewConflict extends BadRequest {
  constructor(message: string) {
    super(message);
    this.name = 'ReviewConflict';
  }
}

